// Foot-anchored sprites, audio transport, fantasy objectives and the tavern board.
let cameraY=0, musicPlayer=null, musicTrack='', summons=[], hubTab='voyages', chosenQuest=5;
function focusCamera(dt){const goal=player.y<125?player.y-180:player.y>420?player.y-250:0;cameraY+=(Math.max(-550,Math.min(440,goal))-cameraY)*Math.min(1,dt*6);}
function verticalOpening(){if(chapter!==0)return;const metal=selected==='nova'?'metal':'stone';solids=solids.filter(p=>p.x<1050&&p.h<25||p.x>=5500&&p.h<25);solids.unshift({x:0,y:452,w:3200,h:100,kind:metal},{x:3200,y:690,w:1100,h:100,kind:metal},{x:4300,y:452,w:2300,h:100,kind:metal});
 const stack=selected==='nova'?[[1100,380,320],[1350,210,390],[1630,40,360],[1900,-130,300],[2400,260,400],[2850,340,230],[3280,300,320],[3570,520,370],[3850,690,400],[4160,452,240],[4420,350,510],[4820,180,450],[5180,-30,330]]:[[1140,380,320],[1390,210,400],[1680,40,370],[1970,-130,240],[2430,330,300],[2790,240,350],[3270,330,350],[3530,530,420],[3850,690,400],[4160,452,240],[4410,350,510],[4780,180,470],[4930,-30,430]];
 for(const [x,y,w] of stack)solids.push({x,y,w,h:17,kind:metal});ladders=ladders.filter(l=>l.x<1050||l.x>=5500);const links=selected==='nova'?[[1140,380,452],[1400,210,380],[1690,40,210],[1950,-130,40],[2460,260,452],[2880,340,452],[3320,300,452],[3600,520,300],[3900,690,520],[4220,452,690],[4470,350,452],[4850,180,350],[5240,-30,180]]:[[1170,380,452],[1420,210,380],[1730,40,210],[2010,-130,40],[2470,330,452],[2830,240,452],[3310,330,452],[3590,530,330],[3900,690,530],[4220,452,690],[4450,350,452],[4840,180,350],[5000,-30,180]];
 for(const [x,endA,endB] of links){const top=Math.min(endA,endB),bottom=Math.max(endA,endB);ladders.push({x,y:top,h:bottom-top});if(!solids.some(p=>Math.abs(p.y-bottom)<1&&x>=p.x&&x<p.x+p.w))solids.push({x:x-55,y:bottom,w:110,h:17,kind:metal});}const key=objects.find(o=>o.id==='key'),cool=objects.find(o=>o.id==='cooling'),data=objects.find(o=>o.id==='data');Object.assign(key,{x:selected==='nova'?2020:2080,y:-150});Object.assign(cool,{x:3990,y:650});Object.assign(data,{x:selected==='nova'?5320:5120,y:-50});for(const e of actors){if(e.origin>3200&&e.origin<4300)e.y=690-e.h;if(e.origin>5000&&e.origin<5500)e.y=-30-e.h;}for(const h of hazards)h.y=690;
 for(const b of covers)if(b.x>3200&&b.x<4300)b.y=690-b.h;
}
function drawFantasyObject(o){if(!assets.fantasy)return;const f=o.id==='key'?0:o.id==='data'?2:1;const im=assets.fantasy,sw=im.width/4;const base=solids.find(p=>o.x>=p.x&&o.x<p.x+p.w&&Math.abs(p.y-o.y)<80);const bottom=base?base.y:o.y+35;ctx.drawImage(im,f*sw,0,sw,im.height,o.x-camera-40,bottom-95,80,95);}
function stepSummons(dt){for(const s of summons){s.life-=dt;s.cd-=dt;s.x+=(player.x-player.face*80-s.x)*Math.min(1,dt*5);s.y=player.y+86;const e=actors.find(e=>!e.dead&&!e.inactive&&Math.abs(e.x-s.x)<250&&Math.abs(e.y-player.y)<100);if(e&&s.cd<=0){damage(e,2);s.cd=.85;particles(e.x+17,e.y+30,'#ba81ef',12);tone(240,.15,.08);}}summons=summons.filter(s=>s.life>0);}
function drawSummons(){if(!assets.fantasy)return;const im=assets.fantasy,sw=im.width/4;for(const s of summons){ctx.save();ctx.globalAlpha=Math.min(.9,s.life);ctx.drawImage(im,sw*3,0,sw,im.height,s.x-camera-35,s.y-95,70,95);ctx.restore();}}
function effect(name){if(!soundOn)return;try{const a=new Audio('assets/audio/'+name+'.wav');a.volume=.5;a.play().catch(()=>{});}catch{}}
audioStart=function(){if(!soundOn)return;try{if(navigator.audioSession)navigator.audioSession.type='playback';audio ||=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});const o=audio.createOscillator(),g=audio.createGain();g.gain.value=0;o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.01);}catch{}ensureMusic(true);};
function ensureMusic(gesture=false){if(typeof Audio==='undefined')return;const name=chapter<2?(selected==='nova'?'stealth':'forest'):'tavern';if(!musicPlayer){musicPlayer=new Audio();musicPlayer.loop=true;musicPlayer.preload='auto';musicPlayer.volume=.32;}if(!soundOn){musicPlayer.pause();return;}if(musicTrack!==name){musicTrack=name;musicPlayer.src='assets/audio/'+name+'.wav';musicPlayer.play().catch(()=>{});}else if(gesture&&musicPlayer.paused)musicPlayer.play().catch(()=>{});}
music=function(dt){ensureMusic();};
addEventListener('pointerdown',()=>audioStart());addEventListener('keydown',()=>audioStart());
function tavernBoard(){chapter=4;const locked=save.scraps.length<4||save.repairs.length<3;const info={5:['The Docks','Break the pirate blockade and bring the first merchant home.','harbor'],6:['Goblin Canopy','Gary needs an eviction notice delivered with extreme prejudice.','forest'],7:['The Hollow Tide','Bring Mr. Fluffy home. Undead dragon. Definitely not a cat.','forest'],8:['Ruins of Bad Decisions','Rescue the second merchant and collect Captain Hangover’s tab.','harbor'],9:['Trial of Clippy','Assemble the Ancient PDF and settle the paperwork.','facility']};const q=info[chosenQuest];const art=q[2]==='forest'?'forest-panorama':q[2]==='facility'?'facility-panorama':'environments';let body;
 if(hubTab==='voyages')body=`<div class="voyage-layout"><nav class="voyage-list">${Object.entries(info).map(([id,v])=>`<button data-select="${id}" class="${+id===chosenQuest?'selected':''}"><small>${save.quests.includes(+id)?'CLEARED':+id===9&&locked?'LOCKED':'VOYAGE '+(+id-4)}</small><b>${v[0]}</b></button>`).join('')}</nav><article class="voyage-detail"><div class="voyage-art ${art==='environments'?'harbor':''}" style="background-image:url(assets/${art}.webp)"></div><h3>${q[0]}</h3><p>${q[1]}</p><div class="reward-strip">${chosenQuest===9?'Final encounter · Captain’s paperwork':save.quests.includes(chosenQuest)?'Replay voyage · Doubloons':'Rescue a resident · Ancient PDF scrap · Doubloons'}</div><button class="primary" id="sail" ${chosenQuest===9&&locked?'disabled':''}>${chosenQuest===9&&locked?'Collect 4 scraps & finish all upgrades':'Set sail →'}</button></article></div>`;
 else if(hubTab==='tavern')body=`<div class="upgrade-grid">${['Roof & lanterns','Bar & furniture','Dock & crew berths'].map((r,i)=>`<article><span class="upgrade-icon">${['✦','⚒','⚓'][i]}</span><h3>${r}</h3><p>${['Repair the roof and light the hall.','Open the bar and furnish the tables.','Build berths for your rescued regulars.'][i]}</p><button data-repair="${i}" class="secondary" ${save.repairs.includes(i)||save.coins<20?'disabled':''}>${save.repairs.includes(i)?'✓ Completed':'Build · 20 gold'}</button></article>`).join('')}</div>`;
 else body=`<div class="crew-grid">${save.crew.length?save.crew.map(w=>`<article><h3>${w}</h3><p>${w==='Mr. Fluffy'?'Undead dragon · structural risk':w==='Gary the Goblin'?'Goblin · unpaid tab':'Merchant · rescued regular'}</p></article>`).join(''):'<p>Your regulars are still stranded. Pick a voyage to bring them home.</p>'}</div>`;
 panel(`<div class="board-heading"><div><p class="eyebrow">Captain’s home port</p><h2>Rum Island Tavern</h2></div><div class="board-stats"><b>◈ ${save.coins}</b><span>${save.scraps.length}/4 scraps · ${save.crew.length}/4 residents</span></div></div><div class="board-tabs">${['voyages','tavern','crew'].map(t=>`<button data-tab="${t}" class="${hubTab===t?'selected':''}">${t==='voyages'?'Voyages':t==='tavern'?'Build the Tavern':'Your Crew'}</button>`).join('')}</div>${body}<footer class="board-footer"><button id="switch" class="secondary">${selected==='nova'?'Nova':'Sylvanas'} · switch character</button><button id="visit" class="secondary">Enter the tavern</button><button id="opening" class="secondary">Replay opening</button><button id="board-sound" class="secondary">Sound ${soundOn?'ON':'OFF'}</button></footer>`);
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{hubTab=b.dataset.tab;tavernBoard();});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{chosenQuest=+b.dataset.select;tavernBoard();});document.querySelectorAll('[data-repair]').forEach(b=>b.onclick=()=>{const i=+b.dataset.repair;if(save.coins<20||save.repairs.includes(i))return;save.coins-=20;save.repairs.push(i);persist();tavernBoard();});if(hubTab==='voyages')$('#sail').onclick=()=>{if(chosenQuest!==9||!locked)start(chosenQuest);};$('#switch').onclick=()=>{selected=selected==='nova'?'sylvanas':'nova';save.character=selected;persist();tavernBoard();};$('#opening').onclick=()=>start(0);$('#board-sound').onclick=()=>{soundOn=!soundOn;audioStart();tavernBoard();};$('#visit').onclick=()=>{start(4);objects=[];mode='visit';talk('Nova','Welcome home, Captain. Try the furniture. It’s mostly load-bearing.');};
}
hub=tavernBoard;
function drawForestCover(b){const x=b.x-camera;rect(x,b.y,b.w,b.h,'#343a36');for(let i=0;i<b.h;i+=18){rect(x+3,b.y+i+2,b.w-6,14,i%36?'#55554a':'#454c42');path([[x+(i%36?b.w*.3:b.w*.65),b.y+i],[x+(i%36?b.w*.3:b.w*.65),b.y+i+18]],'#252e28',2);}rect(x,b.y,b.w,6,'#71845a');for(let i=0;i<b.w;i+=13)path([[x+i,b.y],[x+i+4,b.y+12+(i%19)]],'#586c47',3);}
function drawForestGate(g){const x=g.x-camera;path([[x,30],[x,452]],'#718063',6);for(let y=50;y<450;y+=30){ctx.globalAlpha=.5+Math.sin(clock*3+y)*.2;path([[x-10,y],[x+10,y+12],[x-10,y+24]],'#bf81eb',3);}ctx.globalAlpha=1;}
const oldPlatform=platform;platform=function(s){if(s.kind!=='stone')return oldPlatform(s);const x=s.x-camera;rect(x,s.y,s.w,s.h,'#39413a');for(let i=0;i<s.w;i+=40){rect(x+i+1,s.y+4,38,Math.min(s.h-4,24),'#586052');path([[x+i,s.y+4],[x+i,s.y+s.h]],'#242d28',2);}rect(x,s.y,s.w,4,'#819768');if(s.h<25)for(let i=0;i<s.w;i+=55)path([[x+i+6,s.y+s.h],[x+i+12,s.y+s.h+18]],'#526f49',3);};
window.RumIsland.hub=tavernBoard;

// Deep floors have solid side walls; platforms above remain one-way landings.
function resolveTerrainSide(oldX){for(const s of solids){if(s.h<50||player.y+86<=s.y+3)continue;if(oldX+34<=s.x&&player.x+34>s.x){player.x=s.x-34;player.vx=0;}else if(oldX>=s.x+s.w&&player.x<s.x+s.w){player.x=s.x+s.w;player.vx=0;}}}
function checkFall(){const bottom=Math.max(FLOOR,...solids.map(s=>s.y))+VH;if(!Number.isFinite(player.y)||player.y>bottom){defeat('Lost footing. Return to your last checkpoint, Captain.');return true;}return false;}
const priorDetails=drawMissionDetails;drawMissionDetails=function(){priorDetails();if(chapter!==0)return;for(const edge of [3200,4300]){const x=edge-camera;const y=452;rect(x-13,y-32,26,32,selected==='nova'?'#172d38':'#374630');rect(x-13,y-34,26,4,selected==='nova'?'#eac383':'#b9cf86');for(let i=0;i<3;i++)path([[x-8,y-25+i*7],[x,y-20+i*7],[x+8,y-25+i*7]],'#f6d397',2);rect(x+(edge===3200?-12:0),y,12,238,selected==='nova'?'#344755':'#46533e');for(let k=0;k<238;k+=24)rect(x+(edge===3200?-12:0),y+k,12,3,selected==='nova'?'#779199':'#819768');}};
